	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/me/profile", wrapper.GetProfile)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/me/profile", wrapper.UpdateProfile)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/me/profile", wrapper.CreateProfile)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/daily/{date}", wrapper.GetDaily)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/chart", wrapper.GetChart)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/calendar/{year}/{month}", wrapper.GetCalendar)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/daily/{date}/slots/{slot}/reaction", wrapper.DeleteReaction)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/daily/{date}/slots/{slot}/reaction", wrapper.PutReaction)
